pub fn lower(codepoint: u21) Mapping {
    return lookup(lower_mappings[0..], codepoint);
}

pub fn upper(codepoint: u21) Mapping {
    return lookup(upper_mappings[0..], codepoint);
}

pub fn fold(codepoint: u21) Mapping {
    return lookup(fold_mappings[0..], codepoint);
}

pub fn isCased(codepoint: u21) bool {
    return contains(cased_ranges[0..], codepoint);
}

pub fn isCaseIgnorable(codepoint: u21) bool {
    return contains(case_ignorable_ranges[0..], codepoint);
}

fn lookup(entries: []const Entry, codepoint: u21) Mapping {
    var low: usize = 0;
    var high = entries.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const entry = entries[middle];
        if (codepoint < entry.codepoint) high = middle else if (codepoint > entry.codepoint) low = middle + 1 else return entry.mapping;
    }
    return .{ .values = .{ codepoint, 0, 0 }, .length = 1 };
}

fn contains(ranges: []const Range, codepoint: u21) bool {
    var low: usize = 0;
    var high = ranges.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const range = ranges[middle];
        if (codepoint < range.first) high = middle else if (codepoint > range.last) low = middle + 1 else return true;
    }
    return false;
}
